document.addEventListener('click',e=>{const b=e.target.closest('[data-ice]');if(b)iceHandle(b);const team=e.target.closest('[data-ice-team]');if(team&&game?.session?.ice&&!game.done&&game.lesson.format!=='ice-mystery'){game.session.turn=Number(team.dataset.iceTeam);renderGame();}});
const iceBaseStep=stepActivity;stepActivity=function(dt){if(!game?.session?.ice)return iceBaseStep(dt);const s=game.session;if(game.done||ui.view!=='player'||!s.running||document.hidden||icePicker.open)return;s.seconds=Math.max(0,s.seconds-dt);if($('#ice-clock'))$('#ice-clock').textContent=Math.ceil(s.seconds)+'s';if(!s.seconds){s.running=false;if(Object.keys(s.votes).length)iceCloseVote();else{s.message='Time’s up. Add the class votes, then reveal your speakers.';renderGame();}}};
const iceBaseShow=show;show=function(view){if(view!=='player'&&icePicker.open)iceClosePicker();if(view==='home'&&iceDialog.open)iceDialog.close();return iceBaseShow(view);};
document.addEventListener('DOMContentLoaded',()=>{const state=window.render_game_to_text;window.render_game_to_text=()=>{if(!game?.session?.ice||ui.view!=='player')return state();const s=game.session;return JSON.stringify({view:game.done?'result':'playing',format:game.lesson.format,phase:s.phase,round:s.round,names:s.names,votes:s.votes,speakers:s.speakers,groups:s.groups,turn:s.turn,cells:s.cells,bingoLines:s.wins,seconds:s.seconds,running:s.running,clues:game.lesson.format==='ice-mystery'?s.profiles[s.deck[s.round]]?.slice(0,s.shown):undefined,revealedName:s.phase==='reveal'?s.deck[s.round]:undefined,message:s.message,celebration:game.celebration?{finished:game.celebration.finished}:null});};const params=new URLSearchParams(location.search);if(params.get('subject')==='ice-breakers'&&!params.has('game')){ui.subject='ice-breakers';ui.grade='all';}renderLibrary();});
